import{_ as t,H as i,f as p,i as l}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"21 | 什么是测试工序？","description":"","frontmatter":{},"headers":[{"level":2,"title":"测试工序","slug":"测试工序","link":"#测试工序","children":[]},{"level":2,"title":"可测试性是进程内架构的最重要属性","slug":"可测试性是进程内架构的最重要属性","link":"#可测试性是进程内架构的最重要属性","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"徐昊·AI时代的软件工程/21｜什么是测试工序？.md","filePath":"徐昊·AI时代的软件工程/21｜什么是测试工序？.md","lastUpdated":1795556403000}'),a={name:"徐昊·AI时代的软件工程/21｜什么是测试工序？.md"};function n(s,e,o,r,B,E){return i(),p("div",null,[...e[0]||(e[0]=[l('<h1 id="_21-什么是测试工序" tabindex="-1">21 | 什么是测试工序？ <a class="header-anchor" href="#_21-什么是测试工序" aria-label="Permalink to &quot;21 | 什么是测试工序？&quot;">​</a></h1><p>你好，我是徐昊，今天我们来继续学习 AI 时代的软件工程。</p><p>上节课，我们按照测试策略的指导，遵循前面讲过的测试驱动开发的节奏，完成了一个简单的功能。这个过程中，我们生成的代码符合项目中既有的架构规则。</p><p>我们上节课所采用的方法，就是一个按照测试工序完成编码的例子。今天我们就来讲讲什么是测试工序，以及我们要如何使用它。</p><h2 id="测试工序" tabindex="-1">测试工序 <a class="header-anchor" href="#测试工序" aria-label="Permalink to &quot;测试工序&quot;">​</a></h2><p>工序是指完成特定任务或生产产品所需的一系列步骤或程序。在制造业、生产领域或项目管理中，工序通常用于描述完成特定工作的方法或步骤。每个工序都有其独特的目标、方法和所需的资源。例如，在制造产品时，工序可以包括原材料的采购、加工、装配和质量控制等步骤。</p><p>在项目管理中，工序则可以涵盖项目的规划、执行、监控和收尾等阶段。工序的定义和执行对于确保工作的有效进行和产品的质量至关重要。</p><p>而对于软件开发，工序由测试策略定义。正如前一节课学到的，我们按照测试策略的指引，逐步完成架构中不同组件的开发与集成。这个过程中，测试策略制定了我们所需完成的任务。因此，软件开发中的工序也叫测试工序。</p><p>让我们再来看一下上节课的例子。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/21/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/21/1.png" alt=""></a></p><p>在这个例子中，我们定义了四个测试工序：</p><ol><li><p>使用 Fake 数据库，测试 Persistent 层中的组件；</p></li><li><p>通过 Stub Persistent 层的组件，测试 Application Logic 层中的组件；</p></li><li><p>通过 Stub Application Logic 层的组件，测试 HTTP Interface 层中的组件；</p></li><li><p>使用独立的测试数据库，对三层组件进行功能测试。</p></li></ol><p>无论对于哪个需求，我们都能按照上述工序完成。比如，当我们要面对新需求“按 SKU 商品查询”时，我们可以先按照业务场景，对于商品查询进行场景分解：</p><ol><li><p>当查询的商品存在时，返回查到的商品；</p></li><li><p>当查询的商品不存在时，返回 404。</p></li></ol><p>然后，我们就可以在不同场景下，按照测试工序对场景进行进一步的分解：</p><ol><li>当查询的商品存在时，返回查到的商品。a. Fake 数据库，测试从数据库中查询的 DAO（工序 1）；</li></ol><ul><li><p>b. Stub DAO，测试 Application Logic（工序 2）；</p></li><li><p>c. Stub Application Logic，测试 API 返回 200，以及正确的数据（工序 3）；</p></li><li><p>d 功能测试（工序 4）；</p></li></ul><ol start="2"><li>当查询的商品不存在时，返回 404。a. Fake 数据库，测试从数据库中查询的 DAO（工序 1，同查询商品存在时的工序 1）；</li></ol><ul><li><p>b. Stub DAO，测试 Application Logic（工序 2）；</p></li><li><p>c. Stub Application Logic，测试 API 返回 404（工序 3）；</p></li><li><p>d. 功能测试（工序 4）；</p></li></ul><p>对于其他需求，我们也可以进行类似的分解。需要注意的是，虽然我们最终完成了架构中规定的组件，但我们主要是按照测试策略划分的工序。同样对于上面的例子，如果我们的测试策略发生了改变。比如，因为测试成本或是因为所选用的工具 / 框架存在特殊的限制，我们改变了测试策略：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/21/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/21/2.png" alt=""></a></p><p>在新的测试策略下，我们定义了三个测试工序：</p><ol><li><p>使用 Fake 数据库，测试 Persistent 层中的组件；</p></li><li><p>通过 Stub Persistent 层的组件，测试 HTTP Interface 层和 Application Logic 层中的组件；</p></li><li><p>使用独立的测试数据库，对三层组件进行功能测试。</p></li></ol><p>那么，当我们要面对新需求“按 SKU 商品查询”时，我们的任务分解就变成了这个样子：</p><ol><li>当查询的商品存在时，返回查到的商品。</li></ol><p>a. Fake 数据库，测试从数据库中查询的 DAO（工序 1）；</p><p>b. Stub DAO，测试 API 返回 200，以及正确的数据（工序 2）；</p><p>c. 功能测试（工序 3）；</p><ol start="2"><li>当查询的商品不存在时，返回 404。</li></ol><p>a. Fake 数据库，测试从数据库中查询的 DAO（工序 1，同 1a）；</p><p>b. Stub DAO，测试 API 返回 404（工序 2）；</p><p>c. 功能测试（工序 3）；</p><p>可以看到虽然架构中规定的组件没有改变，但是因为选择了不同的测试策略，就会到得完全不同的工序。</p><p>看到这里，你可能会有疑问，为什么我们不直接从架构上去设计工序，而要依赖于测试策略？这是因为，对于今日的软件开发，可测试性是进程内架构最重要的属性。</p><h2 id="可测试性是进程内架构的最重要属性" tabindex="-1">可测试性是进程内架构的最重要属性 <a class="header-anchor" href="#可测试性是进程内架构的最重要属性" aria-label="Permalink to &quot;可测试性是进程内架构的最重要属性&quot;">​</a></h2><p>大部分进程内架构模式的引入，都意味着在可测试性上的改进。下面让我们看一个例子。</p><p>以前端开发为例，假设我们现在不使用任何框架，直接使用 JavaScript 和 HTML 进行开发。我们默认使用的架构模式是 MVC（Model-View-Controller）架构模式。它将应用程序分成三个主要部分：</p><ol><li><p>模型（Model）：模型代表应用程序的数据和业务逻辑。它负责处理数据的存储、检索、更新和验证。在 MVC 架构中，模型通常独立于用户界面，这意味着它可以用于不同的用户界面或应用程序；</p></li><li><p>视图（View）：视图是用户界面的呈现部分，负责向用户显示数据，并接收用户的输入。它通常包括用户界面元素，如按钮、文本框、图表等。视图负责呈现模型的数据，但不直接处理数据。对于我们的应用而言，视图就是 HTML DOM；</p></li><li><p>控制器（Controller）：控制器是模型和视图之间的中介。它会接收用户的输入（通常来自视图），然后根据输入更新模型或者调用适当的视图来呈现数据。控制器负责应用程序的流程控制和业务逻辑。对于我们的应用而言，控制器就是挂在 HTML DOM 上，监听并响应事件的事件处理逻辑。</p></li></ol><p>由于 HTML DOM 和它上面的事件都难以测试，从实际情况出发，很多团队选择不去对它们进行测试。那么我们当前架构下的测试策略可能是这样的：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/21/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/21/3.png" alt=""></a></p><p>这个测试策略显然存在很大的隐患，容易出错。虽然功能测试覆盖（Q2）了大量代码聚集的视图和控制器部分，但没有考虑到针对前端的功能测试成本很高（运行慢，测试不稳定等等）。Q1 测试过于集中在不易出错且容易测试的模型部分，对于前端反而缺少有效的 Q1 测试来降低成本，提高定位准确性。因而整体测试的投资回报率不高。</p><p>一个很容易想到的改进办法，就是使用 MVP（Model-View—Presenter）架构模式，来改造这个应用。MVP 架构模式是一种软件设计模式，用于开发用户界面。它是一种演变自经典 MVC（Model-View-Controller）模式的设计范式。MVP 模式的核心组成部分包括：</p><ol><li><p>模型（Model）：模型代表应用程序的数据和业务逻辑。它负责处理数据的存储、检索和修改，以及应用程序的核心功能。</p></li><li><p>视图（View）：视图是用户界面的展示部分，负责展示数据并向用户传达信息。它通常是由用户直接与之交互的部分。</p></li><li><p>Presenter：Presenter 是模型和视图之间的中介，负责处理用户输入、更新模型数据并更新视图。Presenter 从模型中检索数据，并将其转换为视图可以理解和展示的形式。Presenter 还接收来自视图的用户输入，对其进行处理并相应地更新模型。</p></li></ol><p>因而我们可以得到新的架构：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/21/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/21/4.png" alt=""></a></p><p>MVP 架构模式引入了不同的组件，我们就有不同的测试策略可以选择了。通常而言，对于视图（View）的测试成本很高。一种流行的测试策略是，忽略对于视图的测试，将测试的重点集中在 Presenter 上。毕竟 Presenter 中封装的是交互逻辑。那么，我们可以通过 Stub 或使用Fake 的 Model，对 Presenter 进行测试。于是我们可以得到以下的测试策略：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/21/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/21/5.png" alt=""></a></p><p>对比 MVC 的架构模式，我们缩小了没有 Q1 测试覆盖的组件范围（View+Controllers 到View）。使 Q1 测试更多覆盖到逻辑密集的部分（Presenter）。单从测试的角度上来看，就能知道，在当前情况下，使用 MVP 架构模式能更好地提高交付质量。</p><p>当然，我们还可以更进一步。针对视图不好测试的问题，行业也在努力寻找解决方案，也出现了新的工具，比如类似于 React Testing Library，Storybook Component Test 或者 Ladle 等等。</p><p>那么，当我们选择使用这些工具时，我们可以将测试的重点放在 View 和 Presenter 上，通过Stub 或 Fake Model 模拟不同的场景，完成对于 View 和 Presenter 的测试，并以此代替功能测试。于是我们可以得到以下的测试策略：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/21/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/21/6.png" alt=""></a></p><p>这显然是一个投资回报率更好的测试策略。因而，我们不需要考虑那么多虚妄的 *-abilities，比如可扩展性等等。单从可测试性角度上来看，我们就能知道，在当前的场景下，MVP 是比MVC 更好的架构模式。而这些，都能从测试策略的改变上发现端倪。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>工序是架构落地的重要手段。架构设计通常是在更高层次上进行的，它定义了系统的结构和组件之间的关系，以及如何满足系统的需求和非功能性属性。然而，要使得架构设计真正生效，需要通过具体的步骤和方法将其实现并落地到实际的开发过程中，而工序就是实现这一目标的关键手段之一。</p><p>工序定义了完成特定任务或生产产品所需的一系列步骤或程序。在软件开发中，工序可以指导开发团队按照预定的流程和方法进行开发工作，确保架构设计的理念和原则得以贯彻执行。通过合理的工序，开发团队可以有序地进行系统开发、集成、测试和部署，从而确保最终交付的软件系统符合设计要求、具备良好的质量和可靠性。</p><p>工序在架构落地过程中扮演着重要的角色，它有助于将抽象的架构设计转化为具体的开发任务和实际的工作流程，帮助团队有效地实现架构设计，并最终产生质量高、可靠性强的软件系统。</p><p>下节课，我们将会学习如何使用 LLM 帮助我们应用工序。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>请将你团队中的架构，按照测试策略转化为工序。</p><p>欢迎在留言区分享你的想法，我会让编辑置顶一些优质回答供大家学习讨论。</p>',60)])])}const c=t(a,[["render",n]]);export{h as __pageData,c as default};
